def segs(g,val):
    H=len(g);W=len(g[0]);seen=set();out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and (r,c) not in seen:
                st=[(r,c)];cells=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen:continue
                    seen.add((y,x));cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==val and abs(dy)+abs(dx)<=1: st.append((ny,nx))
                out.append(cells)
    return out
